package com.grupobigger.unitvv2;
import android.app.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.webkit.*;import android.widget.*;import androidx.media3.common.MediaItem;import androidx.media3.exoplayer.ExoPlayer;import androidx.media3.ui.PlayerView;import org.json.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends Activity{
 final int RED=Color.rgb(105,0,6),PANEL=Color.rgb(35,35,40),WHITE=Color.WHITE,GRAY=Color.rgb(190,190,195);LinearLayout root,tabs,list;FrameLayout stage;PlayerView playerView;ExoPlayer player;WebView web;String base="",user="",pass="";boolean logged=false;String current="TV";final ExecutorService io=Executors.newCachedThreadPool();final Map<String,JSONArray> data=new HashMap<>();
 int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}TextView t(String s,int sp,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(sp);v.setTextColor(c);v.setGravity(Gravity.CENTER_VERTICAL);v.setPadding(dp(12),dp(6),dp(12),dp(6));return v;}GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}Button b(String s){Button v=new Button(this);v.setText(s);v.setAllCaps(false);v.setTextColor(WHITE);v.setTextSize(16);v.setFocusable(true);v.setBackground(bg(Color.rgb(80,80,85),18));v.setOnFocusChangeListener((x,f)->x.setBackground(bg(f?Color.rgb(210,25,40):Color.rgb(80,80,85),18)));return v;}
 @Override public void onCreate(Bundle x){super.onCreate(x);getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);getWindow().getDecorView().setSystemUiVisibility(5894);splash();}
 void splash(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setGravity(Gravity.CENTER);root.setBackgroundColor(Color.rgb(2,13,52));TextView logo=t("▶",64,WHITE);logo.setGravity(Gravity.CENTER);root.addView(logo,new LinearLayout.LayoutParams(-1,dp(110)));TextView n=t("UniTV",26,WHITE);n.setGravity(Gravity.CENTER);root.addView(n,new LinearLayout.LayoutParams(-1,dp(50)));TextView v=t("V 4.19.1.00",15,WHITE);v.setGravity(Gravity.CENTER);root.addView(v,new LinearLayout.LayoutParams(-1,dp(40)));setContentView(root);new Handler().postDelayed(this::home,1200);}
 void home(){if(player!=null){player.release();player=null;}root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(RED);root.setPadding(dp(18),dp(10),dp(18),dp(10));setContentView(root);LinearLayout top=new LinearLayout(this);top.setOrientation(LinearLayout.HORIZONTAL);TextView brand=t("▣  UniTV",23,WHITE);top.addView(brand,new LinearLayout.LayoutParams(0,dp(52),1));Button profile=b("◯  Conta / DNS");profile.setOnClickListener(v->loginDialog());top.addView(profile,new LinearLayout.LayoutParams(dp(190),dp(50)));root.addView(top);HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);tabs=new LinearLayout(this);tabs.setOrientation(LinearLayout.HORIZONTAL);String[] names={"TV","JOGOS","GRATUITO","DESTAQUES","FILMES","SÉRIES","KIDS","ANIME","EXPLORAR"};for(String s:names){Button q=b(s);q.setOnClickListener(v->{current=((Button)v).getText().toString();showTab();});tabs.addView(q,new LinearLayout.LayoutParams(dp(145),dp(58)));}hs.addView(tabs);root.addView(hs,new LinearLayout.LayoutParams(-1,dp(62)));LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.HORIZONTAL);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));ScrollView sv=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setBackgroundColor(Color.argb(70,0,0,0));sv.addView(list);body.addView(sv,new LinearLayout.LayoutParams(0,-1,35));stage=new FrameLayout(this);stage.setBackgroundColor(Color.BLACK);body.addView(stage,new LinearLayout.LayoutParams(0,-1,65));showTab();}
 void showTab(){list.setVisibility(View.VISIBLE);list.removeAllViews();stage.removeAllViews();if(web!=null){web.destroy();web=null;}if(player!=null){player.stop();player.clearMediaItems();}if("JOGOS".equals(current)){showGames();return;}if(!logged){TextView a=t("Faça login para carregar o conteúdo",20,WHITE);a.setGravity(Gravity.CENTER);list.addView(a,new LinearLayout.LayoutParams(-1,dp(90)));TextView p=t("Nenhum conteúdo carregado.\nEntre em Conta / DNS e informe URL, usuário e senha.",21,WHITE);p.setGravity(Gravity.CENTER);stage.addView(p,new FrameLayout.LayoutParams(-1,-1));return;}String key="live";if("FILMES".equals(current)||"DESTAQUES".equals(current)||"KIDS".equals(current)||"ANIME".equals(current)||"EXPLORAR".equals(current))key="vod";else if("SÉRIES".equals(current))key="series";JSONArray arr=data.get(key);if(arr==null){list.addView(t("Carregando...",18,WHITE));return;}renderList(arr,key);playerView=new PlayerView(this);playerView.setUseController(true);stage.addView(playerView,new FrameLayout.LayoutParams(-1,-1));player=new ExoPlayer.Builder(this).build();playerView.setPlayer(player);}
 void renderList(JSONArray arr,String type){TextView h=t(type.equals("live")?"Lista de Canais":type.equals("vod")?"Filmes":"Séries",21,WHITE);list.addView(h,new LinearLayout.LayoutParams(-1,dp(52)));int max=Math.min(arr.length(),600);for(int i=0;i<max;i++){JSONObject o=arr.optJSONObject(i);if(o==null)continue;String name=o.optString("name","Sem nome");Button q=b((i+1)+"  "+name);final JSONObject item=o;q.setOnClickListener(v->{if("series".equals(type))playSeries(item);else playItem(item,type);});list.addView(q,new LinearLayout.LayoutParams(-1,dp(58)));}}
 void playItem(JSONObject o,String type){String id=o.optString("stream_id");String ext=o.optString("container_extension",type.equals("live")?"ts":"mp4");String url=base+"/"+(type.equals("live")?"live":"movie")+"/"+enc(user)+"/"+enc(pass)+"/"+id+"."+ext;play(url);}
 void playSeries(JSONObject s){String id=s.optString("series_id");toast("Carregando episódios...");io.execute(()->{try{JSONObject j=new JSONObject(get(base+"/player_api.php?username="+enc(user)+"&password="+enc(pass)+"&action=get_series_info&series_id="+enc(id)));JSONObject eps=j.optJSONObject("episodes");if(eps==null)throw new Exception();Iterator<String> k=eps.keys();if(!k.hasNext())throw new Exception();JSONArray ar=eps.optJSONArray(k.next());if(ar==null||ar.length()==0)throw new Exception();JSONObject e=ar.optJSONObject(0);String eid=e.optString("id"),ext=e.optString("container_extension","mp4");String u=base+"/series/"+enc(user)+"/"+enc(pass)+"/"+eid+"."+ext;runOnUiThread(()->play(u));}catch(Exception ex){runOnUiThread(()->toast("Não foi possível abrir a série"));}});}
 void play(String url){if(player==null){playerView=new PlayerView(this);stage.removeAllViews();stage.addView(playerView,new FrameLayout.LayoutParams(-1,-1));player=new ExoPlayer.Builder(this).build();playerView.setPlayer(player);}player.setMediaItem(MediaItem.fromUri(url));player.prepare();player.play();}
 void showGames(){list.setVisibility(View.GONE);web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);stage.addView(web,new FrameLayout.LayoutParams(-1,-1));web.loadUrl("file:///android_asset/sports_today.html");}
 void loginDialog(){final Dialog d=new Dialog(this);LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(28),dp(18),dp(28),dp(18));p.setBackground(bg(PANEL,4));TextView h=t("Login / Painel de DNS",25,WHITE);h.setGravity(Gravity.CENTER);p.addView(h,new LinearLayout.LayoutParams(-1,dp(55)));EditText url=new EditText(this);url.setHint("URL / DNS (ex.: http://servidor.com)");url.setSingleLine(true);url.setTextColor(WHITE);url.setHintTextColor(Color.GRAY);url.setText(base);url.setBackgroundColor(Color.rgb(60,60,66));p.addView(url,new LinearLayout.LayoutParams(-1,dp(52)));EditText u=new EditText(this);u.setHint("Usuário");u.setSingleLine(true);u.setTextColor(WHITE);u.setHintTextColor(Color.GRAY);u.setText(user);u.setBackgroundColor(Color.rgb(60,60,66));p.addView(u,new LinearLayout.LayoutParams(-1,dp(52)));EditText pw=new EditText(this);pw.setHint("Senha");pw.setSingleLine(true);pw.setTextColor(WHITE);pw.setHintTextColor(Color.GRAY);pw.setText(pass);pw.setBackgroundColor(Color.rgb(60,60,66));p.addView(pw,new LinearLayout.LayoutParams(-1,dp(52)));Button go=b("Entrar e carregar conteúdo");p.addView(go,new LinearLayout.LayoutParams(-1,dp(58)));TextView st=t("Antes do login nenhum canal é carregado.",15,GRAY);st.setGravity(Gravity.CENTER);p.addView(st,new LinearLayout.LayoutParams(-1,dp(45)));go.setOnClickListener(v->{String bb=url.getText().toString().trim();while(bb.endsWith("/"))bb=bb.substring(0,bb.length()-1);String uu=u.getText().toString().trim(),pp=pw.getText().toString();if(bb.isEmpty()||uu.isEmpty()||pp.isEmpty()){toast("Preencha URL, usuário e senha");return;}final String fb=bb,fu=uu,fp=pp;go.setEnabled(false);st.setText("Validando conta...");io.execute(()->login(fb,fu,fp,d,st,go));});d.setContentView(p);d.setOnShowListener(z->{Window w=d.getWindow();if(w!=null)w.setLayout((int)(getResources().getDisplayMetrics().widthPixels*.52),(int)(getResources().getDisplayMetrics().heightPixels*.78));url.requestFocus();});d.show();}
 void login(String bb,String uu,String pp,Dialog d,TextView st,Button go){try{String auth=get(bb+"/player_api.php?username="+enc(uu)+"&password="+enc(pp));JSONObject j=new JSONObject(auth);JSONObject ui=j.optJSONObject("user_info");if(ui==null||(!"1".equals(ui.optString("auth"))&&!ui.optBoolean("auth",false)))throw new Exception();base=bb;user=uu;pass=pp;data.put("live",new JSONArray(get(api("get_live_streams"))));data.put("vod",new JSONArray(get(api("get_vod_streams"))));data.put("series",new JSONArray(get(api("get_series"))));logged=true;runOnUiThread(()->{d.dismiss();toast("Login OK — conteúdo carregado");current="TV";showTab();});}catch(Exception e){runOnUiThread(()->{st.setText("Usuário, senha ou DNS inválido / servidor indisponível.");go.setEnabled(true);});}}
 String api(String action){return base+"/player_api.php?username="+enc(user)+"&password="+enc(pass)+"&action="+action;}String get(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(9000);c.setReadTimeout(12000);c.setRequestProperty("User-Agent","UniTV-V2/1.0");InputStream in=c.getResponseCode()>=400?c.getErrorStream():c.getInputStream();if(in==null)throw new Exception();BufferedReader r=new BufferedReader(new InputStreamReader(in));StringBuilder s=new StringBuilder();String l;while((l=r.readLine())!=null)s.append(l);return s.toString();}String enc(String s){try{return URLEncoder.encode(s,"UTF-8");}catch(Exception e){return s;}}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}@Override protected void onDestroy(){super.onDestroy();io.shutdownNow();if(player!=null)player.release();}
}
